CREATE PROCEDURE [dbo].[usp_AIMUpdateCheckSqlStatement]
@Sql nvarchar(max) --usp_AIMUpdateCheckSqlStatement "insert into version (version) select '11/03/2016' "
AS

BEGIN SET NOCOUNT ON;
DECLARE @AIMUpdateLogID INT = 0 DECLARE @ProcErrorNumber INT = 0 DECLARE @ProcErrorMessage VARCHAR(200) = ''
BEGIN INSERT dbo.AIMUpdateLog ( BatchID , SqlCommand , CommandType , [Message] , ErrorNumber , UpdateStamp , CFCUserID ) VALUES ( @BatchID , @SqlCommand , @CommandType , @Message , @ErrorNumber , GETDATE() , @CFCUserID
) SET @AIMUpdateLogID = @@IDENTITY END
SELECT @AIMUpdateLogID AS RecordID , @ProcErrorNumber AS ErrorNumber , @ProcErrorMessage AS ErrorMessage
END

BEGIN SET NOCOUNT ON; DECLARE @IDinOtherTable INT DECLARE @ErrorNumber INT = 0 DECLARE @ErrorMessage VARCHAR(200) = ''
IF @AnalyzerNutrientID = 0 BEGIN IF EXISTS(SELECT AnalyzerNutrientCode FROM dbo.AnalyzerNutrient WHERE AnalyzerNutrientCode = @AnalyzerNutrientCode and DataSourceTypeID = @DataSourceTypeID)
BEGIN SET @ErrorNumber = 1 SET @ErrorMessage = 'This Nutrient code already exists. Please enter a different code. Information is not saved!' END ELSE BEGIN INSERT dbo.AnalyzerNutrient ( AnalyzerNutrientCode , AnalyzerNutrientName , UpdateStamp , CFCUserID , DataSourceTypeID , UnitType , ConversionFactor
) VALUES ( @AnalyzerNutrientCode , @AnalyzerNutrientName , GETDATE() , @CFCUserID , @DataSourceTypeID , @UnitType , @ConversionFactor
) END END ELSE BEGIN IF @IsActive = 0 BEGIN SET @IDinOtherTable = ( SELECT XREF.AnalyzerNutrientID FROM dbo.AIMNutrientRefAnalyzerNutrient XREF WITH(NOLOCK) WHERE XREF.AnalyzerNutrientID = @AnalyzerNutrientID
) -- Cross-references are no longer checked/deleted because Nutrient is never "deleted", just inactivated. --IF @IDinOtherTable IS NOT NULL -- BEGIN -- SET @ErrorNumber = 1 -- SET @ErrorMessage = 'Unable to delete nutrient because it is being used in the AIM/Analyzer nutrient cross reference table.' -- END END
IF @ErrorNumber = 0 BEGIN UPDATE dbo.AnalyzerNutrient WITH(ROWLOCK) SET AnalyzerNutrientCode = ISNULL(@AnalyzerNutrientCode, AnalyzerNutrientCode) , AnalyzerNutrientName = ISNULL(@AnalyzerNutrientName, AnalyzerNutrientName) , IsActive = ISNULL(@IsActive, IsActive) , UpdateStamp = GETDATE() , CFCUserID = @CFCUserID , DataSourceTypeID = ISNULL(@DataSourceTypeID, DataSourceTypeID) , UnitType = ISNULL(@UnitType, UnitType) , ConversionFactor = ISNULL(@ConversionFactor, ConversionFactor)
WHERE AnalyzerNutrientID = @AnalyzerNutrientID END END
SELECT @@IDENTITY as RecordID , @ErrorNumber AS ErrorNumber , @ErrorMessage AS ErrorMessage
END

CREATE PROCEDURE [dbo].[usp_AnalyzerPendingSample_SEL_BeginDate_EndDate_DateField]
@BegDate DATE , @EndDate DATE , @DateField INT
AS

BEGIN SET NOCOUNT ON;
SELECT APS.AnalyzerPendingSampleID , APS.SampleID , APS.CreatedStamp , APS.SentStamp , APS.RequestCode , APS.ReceivedStamp , APS.SpectraName , APS.NIRAnalysis FROM dbo.AnalyzerPendingSample APS WITH(NOLOCK) WHERE APS.SentStamp IS NOT NULL AND APS.ReceivedStamp IS NULL
END

BEGIN SET NOCOUNT ON;
SELECT TOP 1 APS.AnalyzerPendingSampleID , APS.SampleID , APS.CreatedStamp , APS.SentStamp , APS.RequestCode , APS.ReceivedStamp , APS.SpectraName , APS.NIRAnalysis FROM dbo.AnalyzerPendingSample APS WITH(NOLOCK) WHERE APS.SampleID = @SampleID AND APS.NIRAnalysis IS NULL
END

BEGIN SET NOCOUNT ON;
SELECT APS.AnalyzerPendingSampleID , APS.SampleID , APS.CreatedStamp , APS.SentStamp , APS.RequestCode , APS.ReceivedStamp , APS.SpectraName , APS.NIRAnalysis FROM dbo.AnalyzerPendingSample APS WHERE APS.SampleID = @SampleID
END

BEGIN SET NOCOUNT ON;
SELECT APS.AnalyzerPendingSampleID , APS.SampleID , APS.CreatedStamp , APS.SentStamp , APS.RequestCode , APS.ReceivedStamp , APS.SpectraName , APS.NIRAnalysis FROM dbo.AnalyzerPendingSample APS WITH(NOLOCK) WHERE APS.SentStamp IS NULL AND APS.NIRAnalysis IS NOT NULL
END

BEGIN SET NOCOUNT ON;
SELECT APS.AnalyzerPendingSampleID , APS.SampleID , APS.CreatedStamp , APS.SentStamp , APS.RequestCode , APS.ReceivedStamp , APS.SpectraName , APS.NIRAnalysis FROM dbo.AnalyzerPendingSample APS WITH(NOLOCK) WHERE APS.NIRAnalysis IS NOT NULL AND (APS.SentStamp IS NULL OR APS.ReceivedStamp IS NULL)
END

SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED; SET XACT_ABORT ON; SET NOCOUNT ON;
INSERT INTO dbo.APILog ( SampleID , APISampleID , DataSourceTypeID , CreateStamp ) VALUES ( @SampleID , @APISampleID , @DataSourceTypeID , GETDATE() )
SELECT @@IDENTITY AS RecordID , @@Error AS ErrorNumber , ERROR_MESSAGE() AS ErrorMessage

BEGIN SET NOCOUNT ON;
SELECT TOP 1 APAM.APIPendingAIMMaterialID , APAM.AIMMaterialID , APAM.DataSourceTypeID , APAM.IsActive , APAM.UpdateStamp , APAM.CFCUserID FROM dbo.APIPendingAIMMaterial APAM WHERE APAM.AIMMaterialID = @AIMMaterialID AND APAM.DataSourceTypeID = @DataSourceTypeID AND APAM.IsActive = @IsActive
