CREATE PROCEDURE [dbo].[usp_Report_AnalysisPivot_GroupByMaterialSupplierLocation] 

	@SampleOwnerID				INT				= NULL , 
	@AIMOwnerLocationID			INT				= NULL , 
	@AIMSourceID				INT				= NULL , 
	@AIMSourceLocationID		INT				= NULL , 
	@ToDate						DATE			= NULL , 
	@FromDate					DATE			= NULL , 
	@AIMMaterialID				INT				= NULL ,    --> if AimMaterialID = 0, the user has selected more than 1 material (and they are in the AIMMaterialLists)
	@Ticket						NVARCHAR(20)	= NULL , 
	@QueryTemplateID			INT				= NULL , 
	@DryMatterBase				BIT				= NULL , 
	@AIMMaterialList			VARCHAR(6000)	= NULL ,    
	@AIMMaterialList2			VARCHAR(6000)	= NULL ,    
	@AIMMaterialList3			VARCHAR(6000)	= NULL 

--exec usp_Report_AnalysisPivot_GroupByMaterialSupplierLocation 0, 0, 0, 0, '2020-08-21', '2020-08-20', 390, '', null, false, '', '', ''

AS

BEGIN
SET NOCOUNT ON;
DECLARE @RecordID INT = 0
DECLARE @ErrorNumber INT = 0
DECLARE @ErrorMessage VARCHAR(200) = ''


    IF EXISTS (SELECT 1 FROM ReportUserDefaultSetting WHERE CFCUserID = @CFCUserID)
    BEGIN
        UPDATE ReportUserDefaultSetting
        SET
            ReportType = @ReportType,
            FromDate = @FromDate,
            ToDate = @ToDate,
            MaterialType = @MaterialType,
            ExtremeOutlier = @ExtremeOutlier,
            MaterialGroup = @MaterialGroup,
            MildOutlier = @MildOutlier,
            SortOnNutrientCode = @SortOnNutrientCode,
            SampleResult = @SampleResult,
            AnalyzerOrFormulation = @AnalyzerOrFormulation,
            QualityControl = @QualityControl,
            DateSampleOrCreated = @DateSampleOrCreated,
            OwnerID = @OwnerID,
            OwnerLocationID = @OwnerLocationID,
            SupplierID = @SupplierID,
            SupplierLocationID = @SupplierLocationID,
            MaterialID = @MaterialID,
            MaterialNameID = @MaterialNameID,
            TestTypeID = @TestTypeID,
			TicketNumber = @TicketNumber,
			TemplateID = @TemplateID,
			CFCUserFormID = @CFCUserFormID,
			OutOfRangeOnly = @OutOfRangeOnly,
			ShowViolations = @ShowViolations
        WHERE CFCUserID = @CFCUserID;
    END
    ELSE
    BEGIN
        INSERT INTO ReportUserDefaultSetting (
            ReportType,
            FromDate,
            ToDate,
            MaterialType,
            ExtremeOutlier,
            MaterialGroup,
            MildOutlier,
            SortOnNutrientCode,
            SampleResult,
            AnalyzerOrFormulation,
            QualityControl,
            DateSampleOrCreated,
            CFCUserID,
            OwnerID,
            OwnerLocationID,
            SupplierID,
            SupplierLocationID,
            MaterialID,
            MaterialNameID,
            TestTypeID,
			TicketNumber,
			TemplateID,
			CFCUserFormID,
			OutOfRangeOnly,
			ShowViolations

        )
        VALUES (
            @ReportType,
            @FromDate,
            @ToDate,
            @MaterialType,
            @ExtremeOutlier,
            @MaterialGroup,
            @MildOutlier,
            @SortOnNutrientCode,
            @SampleResult,
            @AnalyzerOrFormulation,
            @QualityControl,
            @DateSampleOrCreated,
            @CFCUserID,
            @OwnerID,
            @OwnerLocationID,
            @SupplierID,
            @SupplierLocationID,
            @MaterialID,
            @MaterialNameID,
            @TestTypeID,
			@TicketNumber,
			@TemplateID,
			@CFCUserFormID,
			@OutOfRangeOnly,
			@ShowViolations

        );
    END

SET @ErrorNumber = @@ERROR

SELECT
	  @RecordID as RecordID
	, @ErrorNumber AS ErrorNumber
	, @ErrorMessage AS ErrorMessage
END;

