CREATE PROCEDURE [dbo].[usp_UserDefinedDataSourceTemplate_UPD_UseAsSampleCode]
@UserDefinedDataSourceTemplateID INT , @UseAsSampleCodeValue BIT -- 0 or 1 , @CFCUserID INT = NULL
AS

BEGIN SET NOCOUNT ON;
DELETE FROM dbo.DataSourceType WITH(ROWLOCK) WHERE DataSourceTypeID = @DataSourceTypeID
END

BEGIN SET NOCOUNT ON;
DELETE FROM dbo.WarningLimits WITH(ROWLOCK) WHERE WarningLimitsID = @WarningLimitsID
END

BEGIN SET NOCOUNT ON;
DELETE FROM dbo.WebService WITH(ROWLOCK) WHERE WebServiceID = @WebServiceID
END

BEGIN SET NOCOUNT ON;
SELECT W.WebServiceID , W.WebAddress , W.Token , W.Name , W.CFCUserID , W.UpdateStamp , W.DataSourceTypeID , U.UserName FROM dbo.WebService W LEFT OUTER JOIN CFCUser.CFCUser U ON W.CFCUserID = U.CFCUserID
END

BEGIN SET NOCOUNT ON;
SELECT W.WeekID , W.WeekName , W.UpdateStamp FROM dbo.Weeks W WITH(NOLOCK)
END

BEGIN SET NOCOUNT ON;
IF @ConfigID = 0 BEGIN INSERT INTO licensing.Config WITH(ROWLOCK) ( IRUnits , IsOwning , IsAdjustmentRound , NNOMoist , NNODM , TrialUseCount , TrialInstallCode , IsBulkDensityActive , BatchSize , BatchNumberDecimals , IsBatchRound , BatchRoundTo , IsBatchesInteger , NumberNutDecDry , NumberNutDecLiquid , DatabaseDirectory , CompanyName , Address , City , State , Zip , Phone , AuthorizationCode , LeaseCode , LeaseLenght , UnitOfMeasure , IngredientUnitCost , BatchIngredientOrder , IsLiquidBatchVolume , LiquidBatchSize , LiquidBatchNumberDecimals , LiquidBatchIngredientOrder , IsLiquidBatchRound , LiquidBatchRoundTo , IsLiquidBatchesInteger , InstallDate
) VALUES ( @IRUnits , @IsOwning , @IsAdjustmentRound , @NNOMoist , @NNODM , @TrialUseCount , @TrialInstallCode , @IsBulkDensityActive , @BatchSize , @BatchNumberDecimals , @IsBatchRound , @BatchRoundTo , @IsBatchesInteger , @NumberNutDecDry , @NumberNutDecLiquid , @DatabaseDirectory , @CompanyName , @Address , @City , @State , @Zip , @Phone , @AuthorizationCode , @LeaseCode , @LeaseLenght , @UnitOfMeasure , @IngredientUnitCost , @BatchIngredientOrder , @IsLiquidBatchVolume , @LiquidBatchSize , @LiquidBatchNumberDecimals , @LiquidBatchIngredientOrder , @IsLiquidBatchRound , @LiquidBatchRoundTo , @IsLiquidBatchesInteger , @InstallDate ) END ELSE BEGIN UPDATE licensing.Config WITH(ROWLOCK) SET IRUnits = @IRUnits , IsOwning = @IsOwning , IsAdjustmentRound = @IsAdjustmentRound , NNOMoist = @NNOMoist , NNODM = @NNODM , TrialUseCount = @TrialUseCount , TrialInstallCode = @TrialInstallCode , IsBulkDensityActive = @IsBulkDensityActive , BatchSize = @BatchSize , BatchNumberDecimals = @BatchNumberDecimals , IsBatchRound = @IsBatchRound , BatchRoundTo = @BatchRoundTo , IsBatchesInteger = @IsBatchesInteger , NumberNutDecDry = @NumberNutDecDry , NumberNutDecLiquid = @NumberNutDecLiquid , DatabaseDirectory = @DatabaseDirectory , CompanyName = @CompanyName , Address = @Address , City = @City , State = @State , Zip = @Zip , Phone = @Phone , AuthorizationCode = @AuthorizationCode , LeaseCode = @LeaseCode , LeaseLenght = @LeaseLenght , UnitOfMeasure = @UnitOfMeasure , IngredientUnitCost = @IngredientUnitCost , BatchIngredientOrder = @BatchIngredientOrder , IsLiquidBatchVolume = @IsLiquidBatchVolume , LiquidBatchSize = @LiquidBatchSize , LiquidBatchNumberDecimals = @LiquidBatchNumberDecimals , LiquidBatchIngredientOrder = @LiquidBatchIngredientOrder , IsLiquidBatchRound = @IsLiquidBatchRound , LiquidBatchRoundTo = @LiquidBatchRoundTo , IsLiquidBatchesInteger = @IsLiquidBatchesInteger , InstallDate = @InstallDate , UpdateStamp = GETDATE() WHERE ConfigID = @ConfigID END END

BEGIN SET NOCOUNT ON;
UPDATE licensing.Config WITH(ROWLOCK) SET CompanyName = @CompanyName WHERE ConfigID = @ConfigID
END
